--打开主界面系统功能
---@param systemName string
function this.LUA_EVENT_OPENMAINSYSTEMFUNCTION(_, systemName)
    ---@type cfg_MainPanelUI_column
    local tbl = SL:cfg_MainPanelUI_post_GetSystemInfoBySystemId(systemName)
    if tbl and not string.isNullOrEmpty(tbl.command) then
        if tbl.systemId ~= "系统" then
            SL:HideAllKmlPanel()
        end
        local params = string.split(tbl.command, '#')
        local uipanel = params[1]
        local str = params[2]
        local args
        if str then
            local tbl = string.split(str, '&')
            args = {}
            for _, tbl1 in pairs(tbl) do
                local tbl2 = string.split(tbl1, '=')
                if #tbl2 > 1 then
                    args[tbl2[1]] = tonumber(tbl2[2])
                else
                    table.insert(args, tonumber(tbl2[1]))
                end
            end
        end
        GUI:UIPanel_Open(uipanel, nil, nil, args)
        if tbl.systemId ~= "系统" then
            SL.HideMainPanel()
        end
    end
end

--关闭主界面系统功能
---@param panelName string
function this.LUA_EVENT_CLOSEWIN(_, panelName)
    ---@type cfg_MainPanelUI_column
    local tbl = SL:cfg_MainPanelUI_post_GetSystemInfoByPanelName(panelName)
    if tbl then
        SL.ShowMainPanel()
    end
end

