function this.LUA_EVENT_PANEL_Add_SUCCESS(_,control)
    GUI:AddMainPanelUIHideShowPos(control)
end
--界面加载成功
---@param control UIKmlLuaPanelBase
function this.LUA_EVENT_PANEL_LOAD_SUCCESS(_, control)
    local dataList = SL:GetSystemInfoByPanelName(control.panelName)
    ---@param data cfg_system_switch_column
    for i, data in pairs(dataList) do
        if data and data.btnType == ESystemType.Btn  then
            local isShow = SL:GetMetaValue(EMetaVarGetKey.IS_OPEN_SYSTEMFUNCTION, data.systemName)
            SL:ControlSystemPortalVisible(data.btnPath, isShow)
        end
    end
end

