--登录地图
function this.LUA_EVENT_LOGIN_MAP()
    SL.Head:SetHpAnimationSpeed(2)
    -- 不在安全区开启自动战斗
    this.needCheckStartOnHook = true
end

--角色进入地图loading关闭
function this.LUA_EVENT_ENTRY_MAP_LOADING_PANEL_CLOSE()
    -- 不在安全区开启自动战斗
    if this.needCheckStartOnHook and not SL:GetMetaValue(EMetaVarGetKey.GET_IS_SAFEAREA) then
        SL:StartOnHook(true,true)
        this.needCheckStartOnHook = nil
    end
end

--战斗模式改变
---@param data number
function this.LUA_EVENT_PKMODE_CHANGE(_, pkMode)
    SL:SetIsAutoCounterattack(pkMode == EPKMode.Peace)
    SL:AutoCounterattack(pkMode == EPKMode.Peace)
end

--挂机状态改变
---@param onHookStatus EAutoOnHookStatus
function this.LUA_EVENT_ONHOOK_STATE_CHANGE(_, onHookStatus)
    if onHookStatus == EAutoOnHookStatus.OnHooking then
        SL:SetIsAutoCounterattack(false)
    elseif onHookStatus == EAutoOnHookStatus.StopOnHook then
        local pkMode = SL:GetMetaValue(EMetaVarGetKey.PKMODE)
        SL:SetIsAutoCounterattack(pkMode == EPKMode.Peace)
    end
end

---等级改变
function this.LUA_EVENT_LEVELCHANGE(_, level)
    --系统功能开启
    if GUI.uipanels then
        ---@param control UIKmlLuaPanelBase
        for i, controlList in pairs(GUI.uipanels) do
            for i, control in pairs(controlList) do
                local dataList = SL:GetSystemInfoByPanelName(control.panelName)
                ---@param data cfg_system_switch_column
                for i, data in pairs(dataList) do
                    if data then
                        local isShow = SL:GetMetaValue(EMetaVarGetKey.IS_OPEN_SYSTEMFUNCTION, data.systemName)
                        local isFind = SL:ControlSystemPortalVisible(data.btnPath, isShow)
                        if not isFind and isShow then
                            if control.panelName == "KLUISystemLeftPanel" then
                                ---@type KLUISystemLeftPanel
                                local systemLeftPanel = GUI:GetUI("dev/ui/MainUI/Panel/KLUISystemLeft/KLUISystemLeftPanel")
                                if systemLeftPanel then
                                    systemLeftPanel:CreateBtn(data.systemName)
                                end
                            elseif control.panelName == "KLUISystemTopPanel" then
                                ---@type KLUISystemTopPanel
                                local systemTopPanel = GUI:GetUI("dev/ui/MainUI/Panel/KLUISystemTop/KLUISystemTopPanel")
                                if systemTopPanel then
                                    systemTopPanel:CreateBtn(data.systemName)
                                end
                            end
                        end
                    end
                end
            end
        end
    end

    if level == 4 and SL.LoginInfo:IsSDK() then
        SL.SDKMgr:SubmitGameData(ESubmitDataType.Event, "gameTutorial")
    end
end

