---角色创建成功事件
function this.LUA_EVENT_CREATE_PLAYER_SUCCESS(id,rid)
    ---设置召唤兽（宠物）是否显示头顶血条
    local role = SL:GetRoleById(rid)
    if role and role.RoleType == ERoleType.Pet then
        local meRid = SL:GetMetaValue(EMetaVarGetKey.MAIN_ACTOR_ID)
        meRid = tonumber(meRid)
        SL:ShowOrHideHeadHp(role.data.id,role.data.masterId == meRid)
    end
end

--收到好友申请后显示刷新红点
function this.LUA_EVENT_FRIEND_LIST_CHANGE()
    local friendApplyList = SL:GetFriendData(EFriendRelation.ApplyList)
    if friendApplyList and table.count(friendApplyList) > 0 then
        SL:onLUAEvent(LUA_EVENT_BUBBLETIPS_ADD, {id = 27})
    else
        SL:onLUAEvent(LUA_EVENT_BUBBLETIPS_DEL, 27)
    end
    SL:RefreshPanelALLRedStateKmlByCondition("checkReceiveAddFriend")
end

